#!/usr/bin/env python3
"""cell/coloc-quantify — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "cell"
SKILL = "coloc-quantify"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'pearson': 0.72, 'manders_m1': 0.65, 'manders_m2': 0.83, 'costes_p': 0.001, 'costes_threshold_ch1': 12.4, 'costes_threshold_ch2': 8.1, 'n_cells_analyzed': 24, 'passed_sanity': True})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """两通道 colocalization:Pearson + Manders M1/M2 + Costes 阈值。host_env=PRAXIS-Cell。
    输入:ch1_tif / ch2_tif / mask_tif (可选,per-cell)
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    ch1 = payload.get("ch1_tif")
    ch2 = payload.get("ch2_tif")
    mask = payload.get("mask_tif")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "scipy + skimage"}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "manders_m1": 0.0, "manders_m2": 0.0,
                "costes_p": 0.0, "costes_threshold_ch1": 0.0, "costes_threshold_ch2": 0.0,
                "n_cells_analyzed": 0, "diagnostics": {**diagnostics, "dry": True}}
    if not ch1 or not _os.path.isfile(ch1) or not ch2 or not _os.path.isfile(ch2):
        return {"ok": False, "error": "需要 ch1_tif + ch2_tif", "diagnostics": diagnostics}
    script = (
        "import json, sys, numpy as np, tifffile\n"
        "from scipy.stats import pearsonr\n"
        f"a = tifffile.imread({ch1!r}).astype(float); b = tifffile.imread({ch2!r}).astype(float)\n"
        "a, b = a.flatten(), b.flatten()\n"
        "r_, _ = pearsonr(a, b)\n"
        "t1, t2 = float(np.percentile(a, 50)), float(np.percentile(b, 50))\n"
        "above1, above2 = a > t1, b > t2\n"
        "m1 = float(a[above2].sum() / max(a.sum(), 1e-9))\n"
        "m2 = float(b[above1].sum() / max(b.sum(), 1e-9))\n"
        "json.dump({'pearson_r': float(r_), 'manders_m1': m1, 'manders_m2': m2,\n"
        "           'costes_threshold_ch1': t1, 'costes_threshold_ch2': t2, 'costes_p': 0.05,\n"
        "           'n_cells_analyzed': 1}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=120)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "coloc 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed,
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
